矩阵快速幂加速递推来自本人luogu的blog搬运
#include &lt;iostream>
#define ll long long
using namespace std;
const int maxn = 100, maxm = 100;
int i, j, mod;
struct matrix
&#123;
  int n, m;
  ll s[maxn][maxm];
  matrix()
  &#123;
    clean();
  &#125;
  void clean()
  &#123;
    n = maxn, m = maxm;
    for (int i = 0; i &lt; n; i++)
      for (int j = 0; j &lt; n; j++)
        s[i][j] = 0;
  &#125;
&#125; A, F0;                             //F0为初始矩阵，A为构造出的矩阵
long long ss[maxn];
matrix operator*(matrix a, matrix b) //重载*运算符
&#123;
  matrix c;
  if (a.m != b.n)
    return c;
  c.n = a.n, c.m = a.m;
  for (int j = 0; j &lt; c.m; j++)
  &#123;
    for (int i = 0; i &lt; c.n; i++)
      ss[i] = b.s[i][j];
    for (int i = 0; i &lt; c.n; i++)
    &#123;
      for (int k = 0; k &lt; a.m; k++)
        c.s[i][j] += a.s[i][k] * ss[k];
      c.s[i][j] %= mod;
    &#125;
  &#125;
  return c;
&#125;
matrix pow(matrix a, int b)
&#123;
  matrix ans;
  ans.n = a.n, ans.m = a.m;
  for (int i = 0; i &lt; a.n; i++)
    for (int j = 0; j &lt; a.m; j++)
      ans.s[i][j] = (i == j); //构造单位矩阵
  while (b)
  &#123;
    if (b &amp; 1)
      ans = ans * a;
    a = a * a;
    b = b >> 1;
  &#125;
  return ans;
&#125;
int n, k = 2; //k为初始值个数，根据需要取
int main()
&#123;
  for (i = 0; i &lt; k; i++)
    cin >> A.s[0][i];
  for (i = 0; i &lt; k; i++)
    A.s[i][i - 1] = 1;
  for (i = 0; i &lt; k; i++)
    cin >> F0.s[k - i - 1][0];
  cin >> n >> mod;
  A.m = A.n = k, F0.m = 1, F0.n = k;
  if (n &lt; k)
  &#123;
    cout &lt;&lt; F0.s[k - n - 1][0] &lt;&lt; endl;
    return 0;
  &#125;
  cout &lt;&lt; (pow(A, n - k) * F0).s[0][0];
&#125;
